type PendingEngineeringForm={body:Record<string,unknown>;values:Record<string,string>};
function readPendingEngineeringForm(key:string):PendingEngineeringForm|null{try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved&&saved.body&&typeof saved.body.requestId==='string'&&saved.values&&Object.values(saved.values).every(value=>typeof value==='string'))return saved;}catch{/* A unavailable storage backend must not prevent ordinary form use. */}return null;}
function EngineeringForm({dialog,items,boq,userId,storageScope,onClose,saved}:{dialog:Dialog;items:Item[];boq:EngineeringBoqData|null;userId:string;storageScope:string;onClose:()=>void;saved:()=>void}){
  const pendingKey='engineering:pending-form:'+JSON.stringify([storageScope,userId,dialog.path,dialog.method||'POST',dialog.title]);
  const [recovered]=useState(()=>readPendingEngineeringForm(pendingKey));
  const [values,setValues]=useState<Record<string,string>>(()=>recovered?.values||Object.fromEntries(dialog.fields.map(([k,,type])=>[k,dialog.initial?.[k]!==undefined?(type==='measurementLines'?measurementInput(dialog.initial[k]):type==='money'||type==='budget'?String(dialog.initial[k]/100):type==='quantity'?String(dialog.initial[k]/1000):String(dialog.initial[k])):type==='measurementLines'?measurementInput():type==='percent'?'0':type==='date'?localDate():type.startsWith('enum:')?type.slice(5).split(',')[0].split('=')[0]:''])));
  const boqContract=boq?.contracts.find(c=>c.contractId===values.contractId),measurementMode=boqContract?.mode||'free';
  const [busy,setBusy]=useState(false),[error,setError]=useState(''),[uncertain,setUncertain]=useState(!!recovered),[storageWarning,setStorageWarning]=useState('');const frozen=useRef<Record<string,unknown>|null>(recovered?.body||null),submitting=useRef(false);
  useEffect(()=>{if(!busy&&!uncertain)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue='';};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[busy,uncertain]);
  function close(){if(busy)return;if(uncertain&&!confirm('本次保存结果尚未确认。再次打开同一办理表单可恢复原请求，请先确认原操作，避免重复登记。'))return;onClose();}
  function clearPending(){try{sessionStorage.removeItem(pendingKey);}catch{setStorageWarning('浏览器未能清除本次重试记录，请根据已保存结果核对。');}}
  async function submit(e:FormEvent){e.preventDefault();if(submitting.current)return;submitting.current=true;setBusy(true);setError('');try{
    if(!frozen.current){if(dialog.kind==='settlements'&&measurementMode==='boq'&&!values.measurementId)throw new Error('清单合同须选择有效已批准计量单后结算');const data:Record<string,any>={};for(const [k,,type,required] of dialog.fields){const v=values[k]?.trim()||'';if(required&&!v)throw new Error('请填写所有必填字段');data[k]=type==='measurementLines'?parseMeasurementInput(v,measurementMode):type==='money'||type==='budget'?scaled(v,2,type==='budget'?0:1):type==='quantity'?scaled(v,3,1):type==='percent'?Number(v):v;}
      const payload=dialog.envelope?dialog.envelope(data):data;frozen.current=JSON.parse(JSON.stringify({...(payload as object),requestId:crypto.randomUUID()}));try{sessionStorage.setItem(pendingKey,JSON.stringify({body:frozen.current,values}));}catch{setStorageWarning('浏览器无法保存恢复凭据。结果确认前请保持此表单打开，原请求仍可在本页重试。');}
    }
    const result=await api(dialog.path,dialog.method||'POST',frozen.current);if(!result||typeof result!=='object'||!(typeof result.id==='string'||result.ok===true))throw new Error('服务响应缺少保存凭据');clearPending();frozen.current=null;setUncertain(false);saved();
  }catch(ex){const e=ex as Error&{status?:number};const unknown=!!frozen.current&&(!e.status||e.status>=500);setUncertain(unknown);if(!unknown){frozen.current=null;clearPending();}setError(unknown?'未能确认保存结果。请点击“重试同一次保存”，不要重新登记。':e.message);}finally{submitting.current=false;setBusy(false);}}
  return <Modal title={dialog.title} onClose={close} wide><form className="eng-form" onSubmit={submit}>{uncertain&&<p className="eng-message" role="status">上次办理结果尚未确认，已恢复原内容及请求编号。请重试同一次保存；确认结果前内容保持冻结。</p>}{storageWarning&&<p className="error-banner" role="alert">{storageWarning}</p>}<fieldset disabled={busy||uncertain}><div className="eng-form-grid">{dialog.fields.map(([k,label,type,required])=>{required=required||(k==='measurementId'&&measurementMode==='boq');const options=dialog.options?.[k]||(type.startsWith('ref:')?items.filter(r=>r.kind===type.slice(4)&&r.state!=='cancelled'&&!r.voided&&(type!=='ref:measurements'||r.state==='approved'&&r.data.amount>0&&r.data.contractId===values.contractId)&&!(type==='ref:contracts'&&['variations','measurements','settlements'].includes(dialog.kind||'')&&boq?.contracts.some(c=>c.contractId===r.id&&(c.mode==='free'&&!!c.pendingRevisionId||dialog.kind==='variations'&&c.mode==='boq')))).map(r=>({value:r.id,label:r.data.title})):type.startsWith('enum:')?type.slice(5).split(',').map(v=>({value:v.split('=')[0],label:v.split('=')[1]})):null);if(dialog.kind==='tasks'&&k==='progress')return <div key={k} className="eng-derived-field"><span>已批准完成比例</span><strong>{values[k]||'0'}%</strong><small>由日期进度填报并经独立复核后更新。</small></div>;return type==='measurementLines'?<div className="eng-wide" key={k}><EngineeringMeasurementLines value={values[k]} mode={measurementMode} boqContract={boqContract} tasks={items.filter(r=>r.kind==='tasks').map(r=>({id:r.id,state:r.state,data:{title:r.data.title,location:r.data.location}}))} onChange={v=>setValues({...values,[k]:v})}/></div>:<label key={k} className={type==='textarea'?'eng-wide':''}>{label}{required?' *':''}{options?<select value={values[k]} required={required} onChange={e=>setValues({...values,[k]:e.target.value,...(k==='contractId'?{measurementId:'',...(dialog.fields.some(f=>f[2]==='measurementLines')?{lines:measurementInput(undefined,boq?.contracts.find(c=>c.contractId===e.target.value)?.mode||'free')}:{})}:{})})}><option value="">请选择</option>{options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:type==='textarea'?<textarea rows={3} maxLength={2000} required={required} value={values[k]} onChange={e=>setValues({...values,[k]:e.target.value})}/>:<input type={type==='date'?'date':type==='percent'?'number':'text'} inputMode={['money','budget','quantity'].includes(type)?'decimal':undefined} min={type==='percent'?0:undefined} max={type==='percent'?100:undefined} maxLength={200} required={required} readOnly={dialog.kind==='tasks'&&k==='progress'} title={dialog.kind==='tasks'&&k==='progress'?'通过日期进度填报并独立复核后更新':undefined} value={values[k]} onChange={e=>setValues({...values,[k]:e.target.value})}/>}</label>;})}</div></fieldset>{error&&<p className="error-banner" role="alert">{error}</p>}<div className="eng-form-footer"><button type="button" className="button" disabled={busy} onClick={close}>取消</button><button className="button primary" disabled={busy}>{busy?'正在保存…':uncertain?'重试同一次保存':'确认保存'}</button></div></form></Modal>;
}


